import{z as s,x as B,o as E,c as A,q as t,j as i,D as e,d as o,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"显示光刻","description":"","frontmatter":{"title":"显示光刻","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/display-litho.md","filePath":"litho/display-litho.md","lastUpdated":1791063341000}'),p={name:"litho/display-litho.md"};function d(h,a,D,_,m,c){const l=B("Mermaid");return E(),A("div",null,[a[2]||(a[2]=t('<h1 id="显示光刻" tabindex="-1">显示光刻 <a class="header-anchor" href="#显示光刻" aria-label="Permalink to &quot;显示光刻&quot;">​</a></h1><div class="epigraph"><p>Gen 10 玻璃是几米见方；分辨率在微米，均匀性、颗粒和产能按面积计。这是另一门投影光学，不是逻辑扫描机的放大版。</p><footer>—— 对照 FPD（平板显示）光刻机与半导体步进器的尺度分工</footer></div><p><a href="/litho/panel-level-litho">上一课</a>把封装面板做到半米量级。缺口是显示把基板做到米级。本课钉显示光刻。封装步进器作为半导体厂仍会买的大视场机，留给<a href="/litho/packaging-steppers">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TFT/OLED 阵列：线宽微米到亚微米，基板 Gen 号对应边长数米。工具是专用投影或扫描系统（Nikon、Canon 等 FPD 机家族），掩模也是大版。挑战是照度均匀、拼接、掩模 sag、颗粒（缺陷按面积放大）、胶涂布。k1 与 EUV 随机不是这门的语言。</p><p><span class="marginnote">术语翻译：「Gen 号」（Generation）是显示行业给玻璃基板定的尺寸档位——号越大板越大，Gen 10.5 基板约 2.9 m × 3.4 m，比一张乒乓球桌还大。一块板切几块屏、怎么切最省料，是显示厂排产的第一道算术。</span></p><p>缺口是<strong>米级均匀</strong>，不是纳米 NILS。把显示当「很松的光刻」会低估大面积缺陷经济学；把逻辑 EUV 经验直接搬去也会错。</p><p><span class="marginnote">直觉类比：IC 光刻像在邮票上刻微雕，比的是最小线条；显示光刻像在一面墙上印巨幅海报，线条不细但整面墙处处要均匀。海报上一颗墨点不影响远观，可要是正好落在人脸正中，整张就废——缺陷经济学按位置与面积计价。</span></p>',8)),(E(),i(n,null,{default:e(()=>[r(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E4%B8%80%E5%9D%97%20Gen%2010.5%20%E5%9F%BA%E6%9D%BF%22%5D%20--%3E%20CUT%5B%22%E6%8C%89%E5%B0%BA%E5%AF%B8%E5%88%87%E6%88%90%E5%8D%81%E5%87%A0%E8%87%B3%E5%87%A0%E5%8D%81%E5%9D%97%E5%B1%8F%22%5D%0A%20%20G%20--%3E%20DEF%5B%22%E5%90%8C%E6%A0%B7%E7%BC%BA%E9%99%B7%E5%AF%86%E5%BA%A6%E4%B8%8B%2C%20%E7%BB%9D%E5%AF%B9%E7%BC%BA%E9%99%B7%E6%95%B0%E6%9B%B4%E5%A4%9A%22%5D%0A%20%20DEF%20--%3E%20Y%5B%22%E6%9D%BF%E7%BA%A7%E8%89%AF%E7%8E%87%20%3D%20%E5%90%84%E5%B1%8F%E5%85%A8%E5%A5%BD%E7%9A%84%E6%A6%82%E7%8E%87%22%5D%0A%20%20Y%20--%3E%20ECON%5B%22%E4%B8%80%E9%A2%97%E6%9D%80%E6%89%8B%E7%BC%BA%E9%99%B7%E5%B0%B1%E5%BA%9F%E4%B8%80%E5%9D%97%E5%B1%8F%22%5D%0A%20%20ECON%20--%3E%20PRI%5B%22%E9%87%8D%E7%82%B9%3A%20%E9%A2%97%E7%B2%92%E6%8E%A7%E5%88%B6%E4%B8%8E%E7%85%A7%E5%BA%A6%E5%9D%87%E5%8C%80%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="与半导体掩模厂不同" tabindex="-1">与半导体掩模厂不同 <a class="header-anchor" href="#与半导体掩模厂不同" aria-label="Permalink to &quot;与半导体掩模厂不同&quot;">​</a></h3><p>大掩模的写、检验、 pellicle 是另一供应链。不要假设 OASIS.MASK 的 6 寸故事适用。</p><p><span class="marginnote">高分辨率显示（VR、硅基 OLED）会向半导体工具靠拢。本课指大板 FPD 主流。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规格：分辨率、DOV（大焦深）、照度、产能 m²/h。缺陷：按可视面积的杀手定义与 IC \\(A_c\\) 不同（人眼 vs 电学）。规划：与 IC fab 设备不通用。</p><p><span class="marginnote">常见误区：初学者容易按「分辨率不够高」给 FPD 光刻机打低分。实际上它的难点是大视场下照度、焦面、拼接误差处处达标——把 NA 从 0.33 降到 0.1 量级并不难，难的是在三米行程上把均匀性压住；这是另一门工程，不是简化版光刻。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>投影仍是成像，但 NA 低、场大、波长常近 UV。衍射极限远宽于 IC。限制来自工程均匀与缺陷，不是通带截止。</p>',8)),(E(),i(n,null,{default:e(()=>[r(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E7%B1%B3%E7%BA%A7%E7%8E%BB%E7%92%83%22%5D%20--%3E%20FPD%5B%22%E4%BD%8E%20NA%20%E5%A4%A7%E8%A7%86%E5%9C%BA%22%5D%0A%20%20IC%5B%22300%20mm%20%E7%A1%85%22%5D%20--%3E%20SCN%5B%22%E9%AB%98%20NA%20%2F%20EUV%22%5D%0A%20%20FPD%20--%3E%20UNIF%5B%22%E5%9D%87%E5%8C%80%20%2F%20%E9%A2%97%E7%B2%92%20%2F%20%E6%8B%BC%E6%8E%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不讲 LCD 化学。不把硅基微显示与大板混为一谈。本课不进入逻辑节点。</p><p>后课默认：FPD 是独立工具族；下一课半导体封装步进器夹在 IC 与 FPD 之间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>显示光刻是米级低 NA 大视场，墙在均匀与缺陷面积。</li><li>与 IC 扫描机、6 寸掩模链不通用。</li><li>微显示例外地可靠近半导体工具。</li><li>出处：FPD 光刻与半导体步进器的尺度分工通称。</li></ul>',5))])}const f=s(p,[["render",d]]);export{F as __pageData,f as default};
